import type { Grammar, Level, Question, QuestionType, TopicId } from '../types';

// Original guided material. Labels describe this course's scope, not an official JLPT list.
type GuidedGrammar = Grammar & { topicId: TopicId; category: string; level: Level };
type GuidedQuestion = Question & { topicId: TopicId; questionType: QuestionType };
type Form = { before: string; answers: string[]; after: string; en: string; reasons: string[]; note?: string };
const lessons: GuidedGrammar[] = [];
const questions: GuidedQuestion[] = [];

function F(before: string, answers: string[], after: string, en: string, reasons: string[], note?: string): Form {
  return { before, answers, after, en, reasons, note };
}
function L(id: string, title: string, meaning: string, attachment: string[], category: string, topicId: TopicId, level: Level, comparison: string, first: Form, second: Form) {
  const grammarId = `gx-${id}`;
  const examples = [first, second].map(f => ({ ja: f.before + f.answers[0] + f.after, en: f.en }));
  const questionIds = [first, second].map((f, index) => {
    const questionId = `qgx-${id}-${index + 1}`;
    const rotation = questions.length % 4;
    const order = [0, 1, 2, 3].map(n => (n + rotation) % 4);
    const options = order.map((n, j) => ({ id: `${questionId}-o${j + 1}`, text: f.answers[n] }));
    const reasons = [f.note || `${title}: ${meaning} Here the completed sentence means: ${f.en}`, ...f.reasons];
    questions.push({ id: questionId, skill: 'grammar', grammarId, topicId, questionType: 'grammar-form', prompt: `（　）に入る最もよいものを一つ選んでください。\n${f.before}（　）${f.after}`, options, correctOptionId: options[order.indexOf(0)].id, explanations: Object.fromEntries(order.map((n, j) => [options[j].id, reasons[n]])) });
    return questionId;
  });
  lessons.push({ id: grammarId, title, meaning, attachment, category, topicId, level, examples, mistake: { wrong: first.before + first.answers[1] + first.after, correct: examples[0].ja, explanation: first.reasons[0] }, comparison, questionIds });
}

